```js
const fs = require('fs');

const path = './public/'
fs.readdirSync(path, { recursive: true, withFileTypes: false })
.forEach(
  (file) => {
    // check if file is directory, if not then log the path/file
    if (!fs.lstatSync(path+file).isDirectory()) {
      console.log(file);
    };
  },
);
